import type { HTMLAttributes, ReactNode, Ref } from 'react';
import { cn } from '../../utils/cn';
import { SkipLink } from '../../ui/visually-hidden';
import { Logo } from '../../theme/Logo';
import { useTheme } from '../../theme/ThemeProvider';
import { useI18n } from '../../i18n/I18nProvider';
import { authLayoutVariants, type AuthLayoutVariantProps } from './auth-layout.variants';

export interface AuthLayoutProps extends Omit<HTMLAttributes<HTMLDivElement>, 'className' | 'children'> {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** `split` (brand panel + form), `card` (centred card) or `full-bleed` (form on the chrome surface). */
  variant?: AuthLayoutVariantProps['variant'];
  /** The form: heading, fields, submit, alternative sign-in methods. */
  children?: ReactNode;
  /** Brand mark above the form (and in the split brand panel). Defaults to the active preset's Logo with wordmark. */
  logo?: ReactNode;
  /** Split variant: brand panel body (eyebrow, headline, feature list). */
  brand?: ReactNode;
  /** Split variant: line at the bottom of the brand panel (security note, status). */
  brandFooter?: ReactNode;
  /** Accessible name of the brand panel. Defaults to the brand preset's name. */
  brandLabel?: string;
  /** Below the form (switch to sign-up, terms, help). */
  footer?: ReactNode;
  mainId?: string;
  skipLinkLabel?: string;
  fullScreen?: boolean;
}

/**
 * Sign-in / sign-up shell. `split` pairs a brand panel (chrome surface, Logo from the theme's
 * brand preset) with the form and hides the panel below `lg`; `card` centres the form in a card;
 * `full-bleed` puts it straight on the chrome surface. The form comes first in the DOM, so it is
 * first in tab order (after the skip link) on every screen size.
 */
export function AuthLayout({
  variant = 'split',
  children,
  logo,
  brand,
  brandFooter,
  brandLabel,
  footer,
  mainId = 'main',
  skipLinkLabel: skipLinkLabelProp,
  fullScreen = false,
  className,
  ...props
}: AuthLayoutProps) {
  const { t } = useI18n();
  const skipLinkLabel = skipLinkLabelProp ?? t('skip.signIn');
  const theme = useTheme();
  const s = authLayoutVariants({ variant, fullScreen });
  const mark = logo ?? <Logo size={28} wordmark />;
  return (
    <div className={cn(s.root(), className)} {...props}>
      <SkipLink targetId={mainId} className={s.skipLink()}>
        {skipLinkLabel}
      </SkipLink>
      <main id={mainId} tabIndex={-1} className={s.main()}>
        <div className={s.column()}>
          <div className={s.logo()}>{mark}</div>
          <div className={s.surface()}>{children}</div>
          {footer != null && <div className={s.footer()}>{footer}</div>}
        </div>
      </main>
      {variant === 'split' && (
        <aside aria-label={brandLabel ?? theme.brand.name} className={s.brand()}>
          {/* The small-screen logo already names the brand; this one is decorative. */}
          <div aria-hidden>{mark}</div>
          <div className={s.brandBody()}>{brand}</div>
          {brandFooter != null ? <div className={s.brandFooter()}>{brandFooter}</div> : <div />}
        </aside>
      )}
    </div>
  );
}

import { tv, type VariantProps } from '../../utils/tv';

export const authLayoutVariants = tv({
  slots: {
    root: 'relative flex overflow-hidden font-sans text-foreground',
    skipLink: 'focus:absolute',
    main: 'flex min-w-0 flex-1 flex-col items-center overflow-y-auto p-7 outline-none sm:p-10',
    column: 'my-auto flex w-full flex-col',
    logo: 'mb-8 flex',
    surface: 'w-full',
    footer: 'mt-7 text-center text-[13px] text-muted-foreground',
    brand: 'relative hidden w-[46%] max-w-[640px] shrink-0 flex-col justify-between gap-10 overflow-y-auto border-e border-border/60 bg-chrome p-12 lg:order-first lg:flex',
    brandBody: 'max-w-[420px]',
    brandFooter: 'font-mono text-[11.5px] text-muted-foreground',
  },
  variants: {
    variant: {
      split: {
        root: 'bg-background',
        column: 'max-w-[392px]',
        logo: 'lg:hidden',
      },
      card: {
        root: 'bg-background',
        column: 'max-w-[420px] items-center',
        surface: 'rounded-xl border border-border bg-card p-8 text-card-foreground shadow-sm',
        logo: 'justify-center',
      },
      'full-bleed': {
        root: 'bg-chrome',
        main: 'items-stretch',
        column: 'mx-auto max-w-[420px]',
      },
    },
    fullScreen: {
      true: { root: 'h-dvh' },
      false: { root: 'h-full min-h-full' },
    },
  },
  defaultVariants: { variant: 'split', fullScreen: false },
});

export type AuthLayoutVariantProps = VariantProps<typeof authLayoutVariants>;

export { AuthLayout, type AuthLayoutProps } from './AuthLayout';
export { authLayoutVariants, type AuthLayoutVariantProps } from './auth-layout.variants';
export { doc as authLayoutDoc } from './AuthLayout.doc';

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'AuthLayout',
  group: 'Layout',
  status: 'beta',
  description:
    'Sign-in, sign-up and reset shell in three variants: `split` (brand panel on the chrome surface + form; the panel hides below `lg` and the logo moves above the form), `card` (form centred in a card) and `full-bleed` (form straight on the chrome surface). The logo defaults to the ThemeProvider brand preset (Logo with wordmark). The form is first in the DOM, so it is first in tab order on every screen size. Fills its container; `fullScreen` switches to `h-dvh`.',
  pattern: 'landmarks (main, labelled brand aside) + skip link',
  keyboard: [
    ['Tab', 'Skip link first, then the form fields in order, then the footer links'],
    ['Enter on the skip link', 'Moves focus to the form region'],
  ],
  tokens: ['background', 'chrome', 'card', 'card-foreground', 'border', 'muted-foreground', 'primary-text', 'focus-ring'],
};
